 * Parse an expression into a tree.
 *
 * @param {string} input expression source
 * @returns {object} the expression tree; parentheses leave no node behind
 */
export function parse(input) {
  const tokens = tokenize(input);
  let pos = 0;

  function current() {
    return pos < tokens.length ? tokens[pos] : null;
  }

  function advance() {
    pos++;
  }

  function parsePrimary() {
    const token = current();

    if (!token) {
      throw new ExprError(`unexpected end of input at ${input.length}`, input.length);
    }

    // Unary prefix operators
    if (token.type === 'operator' && (token.value === '+' || token.value === '-')) {
      const op = token.value;
      const index = token.index;
      advance();
      const operand = parsePrimary(); // unary binds tightest
      return {
        type: 'unary',
        op,
        operand,
        index,
      };
    }

    // Number
    if (token.type === 'number') {
      advance();
      return {
        type: 'number',
        value: token.value,
        index: token.index,
      };
    }

    // Variable or function call
    if (token.type === 'name') {
      const name = token.value;
      const index = token.index;
      advance();

      // Check for function call
      if (current() && current().type === 'lparen') {
        advance(); // consume '('
        const args = [];

        if (current() && current().type !== 'rparen') {
          args.push(parseExpression(0)); // parse first argument

          while (current() && current().type === 'comma') {
            advance(); // consume ','
            args.push(parseExpression(0)); // parse next argument
          }
        }

        const closeToken = current();
        if (!closeToken || closeToken.type !== 'rparen') {
          throw new ExprError(`missing closing parenthesis at ${input.length}`, input.length);
        }
        advance();
        return {
          type: 'call',
          name,
          args,
          index,
        };
      }

      return {
        type: 'variable',
        name,
        index,
      };
    }

    // Parenthesized expression
    if (token.type === 'lparen') {
      advance();
      const expr = parseExpression(0);
      const closeToken = current();
      if (!closeToken || closeToken.type !== 'rparen') {
        throw new ExprError(`missing closing parenthesis at ${input.length}`, input.length);
      }
      advance();
      return expr;
    }

    throw new ExprError(`unexpected token '${token.value}' at ${token.index}`, token.index);
  }

  function parseExpression(minPrec) {
    let left = parsePrimary();

    while (current()) {
      const token = current();
      if (token.type !== 'operator') break;

      const op = token.value;
      let prec, rightAssoc;

      if (op === '+' || op === '-') {
        prec = 1;
        rightAssoc = false;
      } else if (op === '*' || op === '/' || op === '%') {
        prec = 2;
        rightAssoc = false;
      } else if (op === '^') {
        prec = 4;
        rightAssoc = true;
      } else {
