      if (prec < minPrec) break;

      const opToken = token;
      advance();

      const nextMinPrec = rightAssoc ? prec : prec + 1;
      const right = parseExpression(nextMinPrec);

      left = {
        type: 'binary',
        op,
        left,
        right,
        index: opToken.index,
