    let left = parseMultiplicative();

    while (current()) {
      const token = current();
      if (token.type !== 'operator' || (token.value !== '+' && token.value !== '-')) break;

      const op = token.value;
      const opIndex = token.index;
      advance();
      const right = parseMultiplicative();
      left = {
        type: 'binary',
        op,
        left,
        right,
        index: opIndex,
      };
    }

    return left;
  }

  function parseMultiplicative() {
    let left = parseExponentiation();

    while (current()) {
      const token = current();
      if (token.type !== 'operator' || (token.value !== '*' && token.value !== '/' && token.value !== '%')) break;

      const op = token.value;
      const opIndex = token.index;
      advance();
      const right = parseExponentiation();
      left = {
        type: 'binary',
        op,
        left,
        right,
        index: opIndex,
      };
    }

    return left;
  }

  function parseExponentiation() {
    let left = parseUnary();

    // ^ is right-associative
    if (current() && current().type === 'operator' && current().value === '^') {
      const opIndex = current().index;
      advance();
      const right = parseExponentiation(); // right-associative
      left = {
        type: 'binary',
        op: '^',
        left,
        right,
        index: opIndex,
      };
    }

    return left;
  }

  function parseUnary() {
    const token = current();

    if (token && token.type === 'operator' && (token.value === '+' || token.value === '-')) {
      const op = token.value;
      const index = token.index;
      advance();
      const operand = parseUnary(); // recursive for multiple unary operators
      return {
        type: 'unary',
        op,
        operand,
        index,
      };
    }

    return parsePrimary();
  }

