  const tokens = tokenize(input);
  let pos = 0;

  function current() {
    return pos < tokens.length ? tokens[pos] : null;
  }

  function advance() {
    pos++;
  }

  function parseExpression() {
    return parseAdditive();
  }

  function parseAdditive() {
    let left = parseMultiplicative();

    while (current()) {
      const token = current();
      if (token.type !== 'operator' || (token.value !== '+' && token.value !== '-')) break;

      const op = token.value;
      const opIndex = token.index;
      advance();
      const right = parseMultiplicative();
      left = {
        type: 'binary',
        op,
        left,
        right,
        index: opIndex,
      };
    }

    return left;
  }

  function parseMultiplicative() {
    let left = parseUnary();

    while (current()) {
      const token = current();
      if (token.type !== 'operator' || (token.value !== '*' && token.value !== '/' && token.value !== '%')) break;

      const op = token.value;
      const opIndex = token.index;
      advance();
      const right = parseUnary();
      left = {
        type: 'binary',
        op,
        left,
        right,
        index: opIndex,
      };
    }

    return left;
  }

  function parseUnary() {
    const token = current();

    // Prefix unary operators: +, -
    if (token && token.type === 'operator' && (token.value === '+' || token.value === '-')) {
      const op = token.value;
      const index = token.index;
      advance();
      const operand = parseUnary(); // Recursive for chaining: --3, -+-3, etc.
      return {
        type: 'unary',
        op,
        operand,
        index,
      };
    }

    return parseExponentiation();
  }

  function parseExponentiation() {
    let left = parsePrimary();

    // ^ is right-associative
    if (current() && current().type === 'operator' && current().value === '^') {
      const opIndex = current().index;
      advance();
      const right = parseExponentiation(); // right-associative recursion
      left = {
        type: 'binary',
        op: '^',
        left,
        right,
        index: opIndex,
      };
    }

    return left;
  }

