    const token = current();

    if (!token) {
      throw new ExprError(`unexpected end of input at ${input.length}`, input.length);
    }

    // Number
    if (token.type === 'number') {
      advance();
      return {
        type: 'number',
        value: token.value,
        index: token.index,
      };
    }

    // Variable or function call
